package org.soraworld.areaeffect.command;public final class Args {    private int current;    private final int length;    private final String[] args;    public Args(String[] args) {        this.args = args;        this.current = 0;        this.length = this.args == null ? 0 : this.args.length;    }    public Args(String args) {        this(args == null ? null : args.split(" "));    }    public boolean empty() {        return current >= length;    }    public boolean notEmpty() {        return current < length;    }    public void next() {        if (current < length) {            current++;        }    }    public Args revert() {        if (current > 0) {            current--;        }        return this;    }    public int size() {        return length - current;    }    public String first() {        if (current >= length) {            return "";        }        return args[current];    }    public String get(int index) {        if (current + index >= length) {            return "";        }        return args[current + index];    }}